#define iterations 17
#define formuparam 0.53

#define volsteps 20
#define stepsize 0.1

#define zoom   0.800
#define tile   0.850
#define speed  0.000 

#define brightness 0.0015
#define darkmatter 0.300
#define distfading 0.730
#define saturation 0.850
#define PI 3.141592

// computing rotation matrix
mat2 rot(float a) {
    return mat2(cos(a), -sin(a), sin(a), cos(a));
}

// rainbow gradient palette
vec3 palette(float x) {
    return 0.5 +.5 * cos(vec3(1)*x*2.*PI + vec3(0, 8, 10));
}

// signed distance to a circle
float circle(vec2 p, float r) {
    return length(p) - r;
}

// signed distance to a rectangle
float rect(vec2 p, vec2 s) {
    p = abs(p);
    return max(p.x - s.x, p.y - s.y);
}

// from cartesian -> polar transform
vec2 toPolar(vec2 p) {
    float r = length(p*p);
    float a = atan(p.y, p.x);

    return vec2(r, a);
}

// from polar -> cartesian transform
vec2 fromPolar(vec2 p) {
    return vec2(cos(p.y), sin(p.y))*p.x;
}

// pattern distance function
float pattern(vec2 p) {

    // polar transform
    p = toPolar(p);

    // number of repetions
    float N = 8.;

    // repeat along the radial axis (polar angle)
    p.y = fract(N*p.y/(2.*PI)) - .5;

    // mirror/symmetry, "pushed" together sligtly
    p.y = abs(p.y) + .1;
    p.yx=reflect(p.xy,p.xy);
    // convert back to acrtesian
    p = fromPolar(p);

    // repeat pattern in x and y (tiling), center origin
    p = fract(p*2.) - .5;

    // mirror
    p = abs(p) - .1;

    // KIFS function rotation and mirror in each step


    // save coordinate state to reuse later (bp = "base pointer") 
    vec2 bp = p;
    float d = 1e9;

    // offset first cirlce to the left
    p.y -= .2+1.;
    float c = circle(p, .3);

    // circle outline
    c = abs(c) - .02;

    // reset coordinate to saved state
    p = bp;

    // offset second cirlce to the right
    p.x += .2;
    float c2 = circle(p, .3);

    // circle outline
    c2 = abs(c2) - .02;

    // combine first and second circle
    c = min(c, c2);
    p = bp; 

    // horizontal symmetry for the square
    p.x = abs(p.x)-.35;
    p *= rot(.25*PI);

    float s = rect(p, vec2(.18));

    // outline of the square
    s = abs(s) - .02;  

    // combine circles and squares
    d = min(s, c);

    return d;

}
#define R(p,a,r)mix(a*dot(p,a),p,cos(r))+sin(r)*cross(p,a)
#define H(h)(cos((h)*6.3+vec3(0,23,21))*.5+.5)
void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
	//get coords and direction
	vec2 uv=fragCoord.xy/iResolution.xy-.5;
    uv*=2.;
    uv/=1.-uv.y*1.1;
 vec4 O2=   fragColor;
 vec2 C =fragCoord;
 O2=vec4(0);
    vec3 p,r=iResolution,n=vec3(-.5,-.809,.309),
    d3=normalize(vec3((C-.5*r.xy)/r.y,1));  
    for(float i=0.,e,g=0.;
        ++i<99.;
        O2.xyz+=mix(vec3(1),H(dot(p,p)*.5),.7)*.05*exp(-.05*i*i*e)
    )
    {
        p=g*d3;
        p.z-=10.;
        p=R(p,normalize(vec3(1,2,2)),iTime*.5);
        for(int j=0;j<5;j++)
            p.xy=abs(p.xy),
            p-=2.*min(0.,dot(p,n))*n;
        p.z=fract(5.*log(p.z)-iTime*.5)-.5;
        g+=e=length(p.yz)-.01;
        // Dodecahedron Frame
        //g+=e=length(p.xz)-.01;
    }

      // pixel position normalised to [-1, 1]
	vec2 cPos = -1.0 + 2.0 * fragCoord.xy / iResolution.xy;

    // distance of current pixel from center
	float cLength = length(cPos);


    // waving animation


    // Time varying pixel color
    vec3 col = vec3(0);

    // first layer of pattern
    float d = pattern(uv*2.5);



    // coloring
    col *= palette(abs(uv.x) + abs(uv.x) + d*15.);

    // second layer of pattern
    d = pattern(uv);

    // drawing pattern by collapsing the distance to a defined edge 
    // and inverse (white foreground, black background)
    float pattern = 1.-smoothstep(0.1, 0.22, d);

    // coloring and overlay result over the first pattern
    col = mix(col, pattern*palette((abs(uv.x) + abs(uv.y))+.3+d*10.), pattern);

    // Rug rectangle container
    float rug = rect(uv, vec2(2, 1.1)*0.35);

    // drawing pattern by collapsing the distance to a defined edge
    col *= 1.-smoothstep(0., 0.01, rug);

    // draw outline
    float rugOutline = (1.-smoothstep(0., 0.01, abs(rug)- 0.0015));
    col = mix(col, rugOutline*palette((abs(uv.x)+abs(uv.y))*.2-.2), rugOutline);

    // decorative drame
    float framed = rect(uv, vec2(1.92, .9)*.3);

    framed = abs(framed) - .025;

    float frame = smoothstep(0., 0.01, framed);

    col *= frame;

    // frame circles pattern 
    float circlesd = circle(fract(uv*1.)-.5, 0.35);

    // concentric "onion" layers for
    float circlesd1 = abs(abs(circlesd) - .1) - .04;

    // collapse to defined edge
    float circles = 1.-smoothstep(0., 0.01, circlesd1);

    // draw circles masked by the frame + colorize
    col += (1.-frame)*circles*palette(circlesd*1.5+.1 - (abs(uv.x)+abs(uv.y))*.2);

    // frame outline
    float frameOutline = (1.-smoothstep(0., 0.01, abs(framed-0.01)- 0.0015));

    // overlay frame outline + colorize
    col = mix(col, frameOutline*palette((abs(uv.x)+abs(uv.y))*.2-.2), frameOutline);

      uv += sin(uv.yx*3. + .8*iTime)*.03; 
	vec3 dir=vec3(uv*zoom,(iTime*0.01));
	float time=iTime*speed+.25;


	vec3 from=vec3(1.,.5,0.5);
	from+=vec3(time*2.,time,-2.);


	//volumetric rendering
	float s=0.1,fade=1.;
	vec3 v=vec3(0.);
	for (int r=0; r<volsteps; r++) {
    dir.xy+=cos(cLength*12.0-iTime*0.1) * 0.03;
		vec3 p=from+s*dir*.5;
		p = abs(vec3(tile)-mod(p,vec3(tile*2.))); // tiling fold
		float pa,a=pa=0.;
		for (int i=0; i<iterations; i++) { 
			p=abs(p)/dot(p,p)-formuparam; 
            p.xy*=mat2(cos(iTime*0.01),sin(iTime*0.01),-sin(iTime*0.01),cos(iTime*0.01) );// the magic formula
			a+=abs(length(p)-pa); // absolute sum of average change
			pa=length(p);
		}
		float dm=max(0.,darkmatter-a*a*.001); //dark matter
		a*=a*a; // add contrast
		if (r>6) fade*=1.2-dm; // dark matter, don't render near


		v+=vec3(s,s*s,1.)*a*brightness*fade; // coloring based on distance
		fade*=distfading; // distance fading
		s+=stepsize;
	}
	v=mix(vec3(length(v)),v,saturation); //color adjust
	fragColor = vec4(v*.03*col*O2.xyz,1.);	

}
